function optimalDivision(nums) {
  // Interval DP over every way to split a range into (left) / (right), tracking the largest and smallest
  // value of each range together with its expression; the left side never needs parentheses.
  const memo = new Map();
  const solve = (i, j) => {
    const key = i * 16 + j;
    if (memo.has(key)) return memo.get(key);
    let res;
    if (i === j) res = { hi: [nums[i], String(nums[i])], lo: [nums[i], String(nums[i])] };
    else {
      res = { hi: [-Infinity, ''], lo: [Infinity, ''] };
      for (let m = i; m < j; m++) {
        const left = solve(i, m), right = solve(m + 1, j);
        const wrap = (text) => (m + 1 === j ? text : '(' + text + ')');
        const big = left.hi[0] / right.lo[0];
        if (big > res.hi[0]) res.hi = [big, left.hi[1] + '/' + wrap(right.lo[1])];
        const small = left.lo[0] / right.hi[0];
        if (small < res.lo[0]) res.lo = [small, left.lo[1] + '/' + wrap(right.hi[1])];
      }
    }
    memo.set(key, res);
    return res;
  };
  return solve(0, nums.length - 1).hi[1];
}

