function generate(rand, size) {
  const n = size === 'large' ? 10 : 1 + Math.floor(rand() * 6);
  const top = size === 'large' || rand() < 0.5 ? 1000 : 10;
  return [Array.from({ length: n }, () => 2 + Math.floor(rand() * (top - 1)))];
